/*
 * A170688  Number of reduced words of length n in Coxeter group on 7
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^50 = I.
 * https://oeis.org/A170688
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = number of reduced words of length n in the Coxeter group
 *            on 7 generators, generated by the recurrence derived from the
 *            rational generating function: a(0) = 1 a(1) = 7 a(2) = a(1) * 6
 *            ... a(49) = a(48) * 6 a(50) = 5 * (a(1)+...+a(49)) - 14 a(n) = 5
 *            * (a(n-1)+...+a(n-49)) - 15 * a(n-50) for...
 * Range:     u8 n <= 3, u16 n <= 6, u32 n <= 12, u64 n <= 24, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* The function uses a static cache to allow arbitrary call order. */
seq_t a(idx_t n)
{
    /* static cache for previously computed values */
    static seq_t *cache = NULL;
    static size_t cap = 0;      /* capacity of the cache */
    static idx_t last = 0;      /* highest index computed so far */

    /* initialise the cache on the first call */
    if (cache == NULL) {
        cap = 128;                     /* start with some space */
        cache = (seq_t *)malloc(cap * sizeof(seq_t));
        cache[0] = (seq_t)1;
        last = 0;
    }

    /* expand cache if needed */
    if (n > (idx_t)(cap - 1)) {
        size_t newcap = cap;
        while ((idx_t)(newcap - 1) < n) newcap <<= 1;
        cache = (seq_t *)realloc(cache, newcap * sizeof(seq_t));
        cap = newcap;
    }

    /* compute terms up to n if not already done */
    if (n > last) {
        /* Set the first two explicit terms */
        /* a(0) already set to 1 */
        if (last < 1) {
            cache[1] = (seq_t)7;
            last = 1;
        }

        /* a(2) .. a(49) follow the simple 6‑multiplication rule */
        for (idx_t i = last + 1; i <= n && i <= 49; ++i) {
            if (i == 1) {           /* already handled above */
                /* nothing to do */
            } else if (i == 2) {
                cache[2] = cache[1] * (seq_t)6;
            } else {
                cache[i] = cache[i - 1] * (seq_t)6;
            }
        }

        /* If we reached up to 49, now compute a(50) */
        if (n >= 50 && last < 50) {
            seq_t sum51 = 0;
            for (idx_t k = 1; k <= 49; ++k) sum51 += cache[k];
            /* a(50) = 5 * (a(1)+...+a(49)) - 14  (since a(0)=1) */
            cache[50] = (seq_t)5 * sum51 - (seq_t)14;
            last = 50;
        }

        /* Compute all remaining terms with the recurrence for n ≥ 51 */
        for (idx_t i = last + 1; i <= n; ++i) {
            if (i < 51) {
                /* this should not happen because we handled up to 50 above */
                continue;
            }
            seq_t sum49 = 0;
            for (idx_t k = 1; k <= 49; ++k)
                sum49 += cache[i - k];
            cache[i] = (seq_t)5 * sum49 - (seq_t)15 * cache[i - 50];
        }
        last = n;
    }

    return cache[n];
}
